ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| ImageFileName=/\\(vssadmin|wmic|bcdedit|wbadmin|net1?|sc)\.exe$/i
| regex("(delete\\s+shadows|shadowcopy.*delete|recoveryenabled\\s+no|bootstatuspolicy\\s+ignoreallfailures|delete\\s+catalog|delete\\s+systemstatebackup|stop.*(veeam|backup|sql|MSExchange|vss))", field=CommandLine)
| case {
    ImageFileName=/vssadmin\.exe$/i OR ImageFileName=/wmic\.exe$/i | ActionBucket := "VSS";
    ImageFileName=/bcdedit\.exe$/i                                  | ActionBucket := "BCD";
    ImageFileName=/wbadmin\.exe$/i                                  | ActionBucket := "Wbadmin";
    *                                                                | ActionBucket := "ServiceStop";
}
| NOT UserName=/\$$/
| bucket(span=10m, field=@timestamp)
| groupBy([aid, ComputerName, UserName, _bucket], function=[count(field=ActionBucket, distinct=true, as=DistinctActions), collect([ActionBucket, CommandLine, ParentBaseFileName])])
| DistinctActions >= 3
